package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.HumanReviewTaskEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.HumanReviewTaskMapper; import org.springframework.stereotype.Repository; import java.time.LocalDateTime; import java.util.Optional;
@Repository public class MybatisHumanReviewTaskRepository implements HumanReviewTaskRepository { private final HumanReviewTaskMapper mapper; public MybatisHumanReviewTaskRepository(HumanReviewTaskMapper mapper){this.mapper=mapper;} public int insert(HumanReviewTaskEntity e){return mapper.insert(e);} public Optional<HumanReviewTaskEntity> findById(String id){return Optional.ofNullable(mapper.selectById(id));} public Optional<HumanReviewTaskEntity> findActiveByWorkflowAndType(String id,String type){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<HumanReviewTaskEntity>().eq(HumanReviewTaskEntity::getWorkflowId,id).eq(HumanReviewTaskEntity::getReviewType,type).orderByDesc(HumanReviewTaskEntity::getReviewRound).last("LIMIT 1")));} public int updateTaskStateIfVersionMatches(String id,long version,String status,String decision,String reason){return mapper.update(null,new LambdaUpdateWrapper<HumanReviewTaskEntity>().eq(HumanReviewTaskEntity::getReviewTaskId,id).eq(HumanReviewTaskEntity::getTaskVersion,version).set(HumanReviewTaskEntity::getStatus,status).set(HumanReviewTaskEntity::getDecisionCode,decision).set(HumanReviewTaskEntity::getDecisionReasonCode,reason).set(HumanReviewTaskEntity::getUpdatedAt,LocalDateTime.now()).setSql("taskVersion = taskVersion + 1"));} }
